def grc_revenue_estimate(
    project: str,
    combined_stats: dict,
) -> float | None:
    """
    Returns Average profit per hour crunching given project and GRC price info.
    """
    combined_stats_extract = combined_stats.get(project)
    if not combined_stats_extract:
        log.error(
            "Error: Unable to calculate profitability for project %s bc we have no stats for it"
            % (project)
        )
        return None
    if "COMPILED_STATS" not in combined_stats_extract:
        log.error(
            "Error: Unable to calculate profitability for project %s bc we have no stats for it (COMPILED_STATS)"
            % (project)
        )
        return None
    if (
        avgmagperhour := read_timefloat(
            combined_stats_extract["COMPILED_STATS"]["AVGMAGPERHOUR"],
            time_mode=TIME_MODE,
        )
    ) is None:
        log.error(
            "Error: Unable to calculate profitability for project %s bc we have no stats for it (AVGMAGPERHOUR)"
            % (project)
        )
        return None

    # = grc / (day * mag) * [mag / hour]
    # = grc / (day * mag) * cred / hour * mag / rac
    # = grc / (day * mag) * cred / hour * mag / (cred / day)
    # = grc / (day * mag) * (mag day) / hour
    # = grc / hour
    return MAGNITUDE_UNIT * avgmagperhour


def get_min_grc_per_hour(
    grc_price: float,
    exchange_fee: float,
    min_profit_per_hour: float,
) -> float:
    min_revenue_per_hour = (min_profit_per_hour + HOST_COST_PER_HOUR) / (
        1 - exchange_fee
    )
    min_grc_per_hour = min_revenue_per_hour / grc_price
    return min_grc_per_hour


def profitability_estimate(
    grc_price: float,
    exchange_fee: float,
    project: str,
    combined_stats: CombinedStats,
) -> float | None:
    """
    Returns Average profit per hour crunching given project and GRC price info.
    """
    if not isinstance(grc_price, float) and not isinstance(grc_price, int):
        return None
    grc_per_hour = grc_revenue_estimate(project, combined_stats)
    if grc_per_hour is None:
        return None
    revenue_per_hour = grc_per_hour * grc_price
    exchange_expenses = revenue_per_hour * exchange_fee
    expenses_per_hour = exchange_expenses + HOST_COST_PER_HOUR
    profit_per_hour = revenue_per_hour - expenses_per_hour
    log.debug(
        "Estimating project {} profitability. Rev is {} expenses is {} profit is {}".format(
            project, revenue_per_hour, expenses_per_hour, profit_per_hour
        )
    )
    return profit_per_hour


def profitability_check(
    grc_price: float,
    exchange_fee: float,
    project: str,
    min_profit_per_hour: float,
    combined_stats: CombinedStats,
    profit: float | None = None,
) -> bool:
    """
    Returns True if crunching is profitable right now. False if otherwise or unable to determine.
    """
    if profit is None:
        profit = profitability_estimate(
            grc_price,
            exchange_fee,
            project,
            combined_stats,
        )
    if profit is None:
        return False
    if profit < min_profit_per_hour:
        log.debug(
            "Determined project {} is NOT profitable. Profit is {}".format(
                project, profit
            )
        )
        return False
    log.debug(
        "Determined project {} is profitable. Profit is {}".format(project, profit)
    )
    return True


def get_latest_wu_date(combined_stats_extract: Iterable[str]) -> datetime.datetime:
    """
    Given list of WUs, return latest date or 1993 if unable to find one
    @param combined_stats_extract:
    @return:
    """
    latest_date = datetime.datetime.fromtimestamp(0)
    for date in combined_stats_extract:
        datetimed = date_to_date(date)
        if datetimed > latest_date:
            latest_date = datetimed
    return latest_date


def benchmark_check(
    project_url: str,
    combined_stats: CombinedStats,
    benchmarking_minimum_wus: float,
    benchmarking_minimum_time: float,
    benchmarking_delay_in_days: float,
    skip_benchmarking: bool,
) -> bool:
    """
    Returns True if we should force crunch this project for benchmarking reasons. False otherwise
    """
    if skip_benchmarking:
        return False
    combined_stats_extract = combined_stats.get(project_url)
    if not combined_stats_extract:
        log.error("Unable to find project in benchmark_check".format(project_url))
        return True
    if (
        read_timefloat(
            combined_stats_extract.get("COMPILED_STATS", {}).get("TOTALTIME", {}),
            time_mode=TIME_MODE,
        )
        or 0
    ) < benchmarking_minimum_time:
        log.debug(
            "Forcing WU fetch on {} due to BENCHMARKING_MINIMUM_TIME".format(
                project_url
            )
        )
        return True
    if (
        combined_stats_extract["COMPILED_STATS"]["TOTALTASKS"]
        < benchmarking_minimum_wus
    ):
        log.debug(
            "Forcing WU fetch on {} due to benchmarking_minimum_tasks".format(
                project_url
            )
        )
        return True
    latest_date = get_latest_wu_date(combined_stats_extract["WU_HISTORY"])
    delta = datetime.datetime.now() - latest_date
    if abs(delta.days) > benchmarking_delay_in_days:
        log.debug(
            "Forcing WU fetch on {} due to BENCHMARKING_DELAY_IN_DAYS latest WU was {}".format(
                project_url, latest_date
            )
        )
        return True
    return False


