        TEMP_TARGET_CTL.min_error = (TARGET_TEMP_MAX - TARGET_TEMP_MIN) / 2
        TEMP_TARGET_CTL.ctrl = (TEMP_TARGET_CTL.ctrl_min + TEMP_TARGET_CTL.ctrl_max) / 2
